#include "../Source/SampleTools.h"
#include "../Source/UserWavetable.h"
#include "../Source/HybridOscillator.h"
#include <iostream>
#include <stdexcept>
void check(bool x,const char* s){if(!x)throw std::runtime_error(s);}
int main(){eg::SampleData s;s.rate=48000;s.left.resize(48000);s.right.resize(48000);for(int i=0;i<48000;++i)s.left[i]=s.right[i]=.7f*std::sin(6.283185307179586*440*i/48000);auto a=eg::analyseSample(s);check(a.root==69&&a.confidence>.8,"pitch detection");auto z=eg::nearestZero(s,1000);check(std::abs(s.left[z])<.1,"zero crossing");auto t=eg::transformSample(s,0,s.frames(),1.5f,7);check(t&&t->frames()==72000,"stretch duration");for(float x:t->left)check(std::isfinite(x),"stretch finite");auto pitch=eg::analyseSample(*t);check(std::abs(pitch.root-76)<=1,"pitch shift");std::vector<float> x(2048);for(int i=0;i<1024;++i){x[i]=std::sin(6.283185307179586*i/1024);x[1024+i]=std::cos(6.283185307179586*i/1024);}auto w=eg::UserWavetable::build(x,1024);check(w&&w->data.size()==2,"wavetable frame count");check(std::abs(w->read(0,0,0))<.01&&w->read(0,0,1)>.9,"wavetable morph");check(!eg::UserWavetable::build(x,1000),"invalid frame format");eg::SampleData pulse;pulse.rate=48000;pulse.left.assign(48000,0);pulse.right=pulse.left;for(int k:{4800,14400,28800})for(int j=0;j<480;++j)pulse.left[k+j]=pulse.right[k+j]=.8f;auto trans=eg::analyseSample(pulse);check(trans.slices.size()>=4,"transient detection");std::vector<float> loop(100,1);for(int i=0;i<50;++i)loop[i]=-1;check(eg::loopSample(loop,99,0,100,10,false)<-.7,"forward crossfade");check(eg::loopSample(loop,0,0,100,10,true)>.7,"reverse crossfade");eg::HybridParams p;p.mode=10;p.shape=.7;eg::HybridConfig cfg;cfg.set(p);cfg.user=w.get();eg::HybridVoice voice;double energy=0;for(int i=0;i<2048;++i){auto z=voice.process(eg::HybridTables::instance(),cfg,440,440,48000);check(std::isfinite(z.l),"custom WT finite");energy+=z.l*z.l;}check(energy>1,"custom WT audio");std::cout<<"Sample analysis, stretch, pitch, transient, loop and wavetable PASS\n";}
